import React, { useEffect, useRef } from "react"

interface RevealProps {
  className?: string
  /** 阶梯延迟档位，对应 .reveal-delay-N */
  delay?: 0 | 1 | 2 | 3
  children: React.ReactNode
}

/**
 * 滚动入场容器：进入视口时加 .reveal-visible（只触发一次）。
 * 隐藏态由 CSS `[data-js] .reveal:not(.reveal-visible)` 承担——JS 不可用时
 * （无 data-js 标记）内容直接可见；reduced-motion 由 CSS media query 兜底直接显示。
 */
function Reveal({ className = "", delay = 0, children }: RevealProps): React.ReactElement {
  const ref = useRef<HTMLDivElement>(null)

  useEffect(() => {
    const el = ref.current
    if (!el) return
    if (typeof IntersectionObserver === "undefined") {
      el.classList.add("reveal-visible")
      return
    }
    // 挂载即同步判定：已在视口（含 15% 提前量）内的直接显示。
    // IO 首帧回调依赖渲染帧投递，帧停滞（窗口遮挡、主线程阻塞、
    // 后台标签页）时可能一直不来，首屏内容会卡在隐藏态直到滚动。
    const rect = el.getBoundingClientRect()
    const earlyTrigger = window.innerHeight * 0.15
    if (rect.top < window.innerHeight + earlyTrigger) {
      el.classList.add("reveal-visible")
      return
    }
    const io = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add("reveal-visible")
            io.unobserve(entry.target)
          }
        })
      },
      // 提前触发：底部外扩 15% 视口高度 + threshold 0，元素进入视口前
      // 过渡已开始，避免「滚到了才开始加载」的卡顿感（高区块尤甚：
      // threshold 0.15 对 2677px 的区块意味着要露出 400px 才触发）
      { threshold: 0, rootMargin: "0px 0px 15% 0px" }
    )
    io.observe(el)
    return () => io.disconnect()
  }, [])

  const delayClass = delay > 0 ? ` reveal-delay-${delay}` : ""
  return (
    <div ref={ref} className={`reveal${delayClass} ${className}`.trim()}>
      {children}
    </div>
  )
}

export default Reveal
