import React from "react"
import { Link, graphql, PageProps } from "gatsby"
import { Books, Calendar, FileText } from "@phosphor-icons/react"
import Layout from "../components/layout"
import SEO from "../components/seo"
import { Reveal } from "../components/animations"
import { SERIES } from "../data/series"

interface SeriesAggregate {
  id: string
  count: number
  latestDate: string | null
}

interface SeriesPageContext {
  seriesAggregates?: SeriesAggregate[]
}

interface SeriesPageData {
  site: {
    siteMetadata: {
      title: string
    }
  }
}

/**
 * 系列列表页：系列元数据来自 src/data/series.ts，篇数与最新日期由
 * gatsby-node.ts 的 onCreatePage 在构建期聚合后通过 pageContext 注入，
 * 避免本页 GraphQL 查询拉全量文章。
 */
const SeriesPage: React.FC<PageProps<SeriesPageData, SeriesPageContext>> = ({
  data,
  pageContext,
  location,
}) => {
  const siteTitle = data.site.siteMetadata.title
  const aggregates = new Map(
    (pageContext.seriesAggregates ?? []).map((a) => [a.id, a])
  )
  const seriesList = SERIES.map((def) => ({
    def,
    count: aggregates.get(def.id)?.count ?? 0,
    latestDate: aggregates.get(def.id)?.latestDate ?? null,
  })).filter((item) => item.count > 0)

  const formatDate = (raw: string): string => {
    const date = new Date(raw)
    if (Number.isNaN(date.getTime())) {
      return raw
    }
    return `${date.getFullYear()}年${String(date.getMonth() + 1).padStart(
      2,
      "0"
    )}月${String(date.getDate()).padStart(2, "0")}日`
  }

  return (
    <Layout location={location} title={siteTitle}>
      <SEO
        title="系列"
        description="系列专题：围绕同一主题连续写作的成组文章"
        keywords={["系列", "series", "专题", "blog"]}
      />

      <header className="mb-8 text-center fade-in">
        <div className="inline-flex items-center justify-center w-12 h-12 rounded-xl bg-accent-subtle mb-3">
          <Books className="w-6 h-6 text-accent" weight="duotone" />
        </div>
        <h1 className="text-2xl font-bold text-foreground mb-2 font-serif">
          系列
        </h1>
        <p className="text-foreground-secondary text-sm max-w-md mx-auto">
          围绕同一主题连续写作的成组文章，共{" "}
          <span className="text-accent font-semibold">{seriesList.length}</span>{" "}
          个系列
        </p>
      </header>

      {seriesList.length === 0 ? (
        <div className="text-center py-16 fade-in">
          <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-background-secondary mb-3">
            <Books
              className="w-8 h-8 text-foreground-muted"
              weight="duotone"
            />
          </div>
          <p className="text-foreground-secondary text-sm">暂无系列</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 max-w-3xl mx-auto">
          {seriesList.map(({ def, count, latestDate }, index) => (
            <Reveal key={def.id} delay={(index % 4) as 0 | 1 | 2 | 3}>
              <Link
                to={`/series/${def.id}/`}
                className="group block h-full p-5 rounded-2xl bg-background-card shadow-xs hover:shadow-md transition-all duration-200"
              >
                <h2
                  className="text-base font-bold text-foreground group-hover:text-accent transition-colors duration-200 mb-2"
                  style={{ fontFamily: '"Noto Serif SC", Georgia, serif' }}
                >
                  《{def.title}》
                </h2>
                <p className="text-xs text-foreground-secondary leading-relaxed mb-3 line-clamp-2">
                  {def.description}
                </p>
                <div className="flex flex-wrap items-center gap-3 text-[11px] text-foreground-muted">
                  <span className="inline-flex items-center gap-1">
                    <FileText className="w-3 h-3" weight="duotone" />
                    共 <span className="text-accent font-semibold">{count}</span>{" "}
                    篇
                  </span>
                  {latestDate && (
                    <span className="inline-flex items-center gap-1">
                      <Calendar className="w-3 h-3" weight="duotone" />
                      最新 {formatDate(latestDate)}
                    </span>
                  )}
                </div>
              </Link>
            </Reveal>
          ))}
        </div>
      )}
    </Layout>
  )
}

export default SeriesPage

export const pageQuery = graphql`
  query {
    site {
      siteMetadata {
        title
      }
    }
  }
`
